{
  "sea_level": 63,
  "disable_mob_generation": false,
  "aquifers_enabled": true,
  "ore_veins_enabled": true,
  "legacy_random_source": false,
  "default_block": {
    "Name": "minecraft:stone"
  },
  "default_fluid": {
    "Name": "minecraft:water"
  },
  "noise": {
    "min_y": -64,
    "height": 384,
    "size_horizontal": 1,
    "size_vertical": 2
  },
  "noise_router": "minecraft:overworld",
  "spawn_target": "minecraft:overworld",
  "surface_rule": {
    "type": "minecraft:rule",
    "sequence": [
      {
        "if_true": {
          "type": "minecraft:and",
          "values": [
            {
              "type": "minecraft:stone_depth",
              "surface_type": "floor",
              "offset": 0,
              "add_surface_depth": false
            },
            {
              "type": "minecraft:above_preliminary_surface"
            }
          ]
        },
        "then_run": {
          "type": "minecraft:block",
          "result_state": {
            "Name": "boundless_horizons_world:dead_grass_block"
          }
        }
      },
      {
        "if_true": {
          "type": "minecraft:stone_depth",
          "surface_type": "floor",
          "offset": 1,
          "add_surface_depth": false
        },
        "then_run": {
          "type": "minecraft:block",
          "result_state": {
            "Name": "boundless_horizons_world:dead_dirt"
          }
        }
      },
      {
        "if_true": {
          "type": "minecraft:stone_depth",
          "surface_type": "floor",
          "offset": 2,
          "add_surface_depth": false
        },
        "then_run": {
          "type": "minecraft:block",
          "result_state": {
            "Name": "boundless_horizons_world:dead_dirt"
          }
        }
      }
    ]
  },
  "spawn_target_heightmap": "WORLD_SURFACE_WG",
  "surface_block_state": {
    "Name": "minecraft:grass_block"
  },
  "noise_caves_enabled": true,
  "aquifer_fluid_level_spread": 4,
  "aquifer_fluid_level_floodedness": 0,
  "aquifer_fluid_level_lava": 32,
  "ore_veins": {
    "copper": true,
    "iron": true,
    "gold": true
  },
  "default_fluid_level": 63
}
